"""Bind source provenance, unchanged rock assets and actual engine evidence."""
import argparse,hashlib,json
from datetime import datetime,timezone
from pathlib import Path

def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--note',required=True);a=p.parse_args();root=a.root.resolve();project=root/'projects/aquascape-sand-trial-v1';game=root/'projects/fishing-2d/game';review=root/'projects/fishing-2d/plans/reviews/aquascape-sand-v1'
    native=read(review/'godot/render.validation.json');handoff=read(review/'production.handoff.json');assets=read(game/'assets/aquascape-sand-v1/assets-manifest.json');source_manifest=read(project/'output/assets-manifest.json')
    if not native['ok'] or not handoff['ok'] or not handoff['native_review_executed']:raise ValueError('Native checks failed/missing')
    if 'ERROR:' in (review/'capture-console.log').read_text(encoding='utf-8'):raise ValueError('Native engine logged errors')
    if source_manifest['assets']['fine_sand']['review']['status']!='accepted':raise ValueError('Unreviewed source')
    if not all(native['checks'].values()):raise ValueError('Failed native interaction check')
    hashes={}
    def add(path):
        path=Path(path);path=path if path.is_absolute() else root/path;hashes[path.relative_to(root).as_posix()]=sha(path);return path
    for row in assets['assets']:
        model=add(row['path'])
        if sha(model)!=row['sha256']:raise ValueError('Runtime asset changed')
        if row['id']=='fine_sand':
            source=add(row['source'])
            if sha(source)!=row['source_sha256'] or sha(source)!=sha(model):raise ValueError('Source resolution/art bytes changed')
    for name in ['EditableSandBed','SandPlacementLab','SandPlacementReview']:
        original=add(root/f'resources/runtime/godot/aquascape/{name}.gd');deployed=add(game/f'scripts/aquarium/{name}.gd')
        if sha(original)!=sha(deployed):raise ValueError('Deployment is stale')
    catalog=read(game/'assets/aquascape-v5/catalog.json')
    for id in ['rock','river_boulder']:
        spec=next(r for r in catalog['assets'] if r['id']==id)
        for view in ['front','right','top']:add(game/spec['material_dir'].removeprefix('res://')/(id+'-'+view+'.png'))
    for path in [*project.glob('*.json'),project/'pipeline/manifest.json',project/'pipeline/progress.json',project/'plans/fine_sand.json',project/'output/assets-manifest.json',game/'assets/aquascape-sand-v1/assets-manifest.json',game/'assets/aquascape-sand-v1/fine-sand.png.import',game/'assets/aquascape-v5/catalog.json',game/'scripts/aquarium/ThreeViewArtwork.gdshader',game/'scenes/aquascape_sand_lab.tscn',game/'scenes/aquascape_sand_review.tscn',root/'projects/fishing-2d/open-aquascape-sand-v1.cmd',root/'projects/fishing-2d/docs/AQUASCAPE-SAND-TRIAL-V1.md',root/'projects/fishing-2d/plans/changes/aquascape-sand-trial-v1.production-delta.json',root/'resources/scripts/aquascape/produce_sand_trial.py',Path(__file__).resolve(),review/'production.handoff.json',review/'godot/render.validation.json',review/'capture-console.log',review/'import-console.log',review/'godot/test-save.json']:
        if Path(path).exists():add(path)
    for path in native['outputs']:add(path)
    report={'schema_version':1,'command':'aquascape.record-sand-trial-review','ok':True,'status':'done','next_action':'human_review','outputs':{'scene':'res://scenes/aquascape_sand_lab.tscn','launcher':str(root/'projects/fishing-2d/open-aquascape-sand-v1.cmd'),'source_prompt':str(project/'plans/fine_sand.json'),'screenshots':native['outputs']},'summary':native['summary'],'native_checks_passed':len(native['checks']),'source_review':{'workflow':'done/human_review','operator_asset_review':'accepted','art_method':'Foundry workflow configured openai/gpt-image-2; one full-bleed 1024x1024 generated sand material using existing fish artwork for style.','source_bytes_preserved':True},'operator_visual_review':{'status':'reviewed_trial','at':datetime.now(timezone.utc).isoformat(),'note':a.note},'user_acceptance':'pending','scope':'One sand and two reused rocks in a separate editable substrate trial. Existing game scenes, fish, rods and aquarium saves are outside scope.','limitations':native['limitations']+['Native source art uses nearest sampling and a fixed repeat scale; very distant views can still alias.','No poured-grain particle effect or water turbidity is implemented in this first interaction trial.','The source-only project also contains generic scaffold tasks generated by the toolkit; these are not the target gameplay scope. Completed construction is tracked by the sand trial Production Delta and this hash-bound native report.'],'hashes':hashes,'failures':[]}
    (review/'validation-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'ok':True,'next_action':'human_review','native_checks_passed':len(native['checks']),'hash_bound_files':len(hashes),'summary':native['summary']}))

if __name__=='__main__':main()
